DO $$
DECLARE
  rec RECORD;
  cur_view_count INT;
  cur_tier VARCHAR(20);
BEGIN
  FOR rec IN SELECT * FROM story_events ORDER BY event_id LOOP
    SELECT view_count, tier INTO cur_view_count, cur_tier FROM stories WHERE story_id = rec.story_id;

    IF rec.event_type = 1 AND cur_tier = 'active' THEN
      UPDATE stories SET view_count = view_count + rec.view_increment WHERE story_id = rec.story_id;
    ELSIF rec.event_type = 2 AND cur_view_count >= 100 AND cur_tier = 'active' THEN
      UPDATE stories SET tier = 'trending' WHERE story_id = rec.story_id;
    ELSIF rec.event_type = 3 AND cur_tier <> 'archived' THEN
      UPDATE stories SET tier = 'archived' WHERE story_id = rec.story_id;
    END IF;
  END LOOP;
END $$;

SELECT * FROM stories ORDER BY story_id;
